+    && Number.isFinite((item as DurationObservation).duration)
+    && typeof (item as DurationObservation).recordedAt === 'number'
+    && Number.isFinite((item as DurationObservation).recordedAt)
+  ))
+  return parsed.length ? parsed : null
+}
