+export async function readDurationHistory(path: string, ttl: number): Promise<DurationHistory | null> {
+  try {
+    const json = JSON.parse(await readFile(path, 'utf8'))
+    if (!json || typeof json !== 'object' || Array.isArray(json)) {
+      return null
+    }
+    const cutoff = ttl > 0 ? Date.now() - ttl : -Infinity
+    return Object.fromEntries(Object.entries(json).flatMap(([file, value]) => {
+      const entries = observations(value)?.filter(item => item.recordedAt === 0 || item.recordedAt >= cutoff)
+      return entries?.length ? [[file, entries]] : []
+    }))
+  }
+  catch {
